previewCss:
.darma-loader-darma-b13-star-rating { --accent: var(--loader-color, #facc15); --accent-2: var(--loader-secondary-color, #94a3b8); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .2); display: flex; gap: 4%; }
.darma-loader-darma-b13-star-rating span { position: relative; flex: 1; overflow: hidden; background: color-mix(in srgb, #000 14%, var(--accent-2)); clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%); }
.darma-loader-darma-b13-star-rating span::after { content: ''; position: absolute; top: 0; left: 0; width: 0; height: 100%; background: var(--accent); animation: darma-loader-darma-b13-star-rating-rate calc(var(--loader-speed, 1s) * 2.6) ease-out infinite; }
.darma-loader-darma-b13-star-rating span:nth-child(2)::after { animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b13-star-rating span:nth-child(3)::after { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b13-star-rating span:nth-child(4)::after { animation-delay: calc(var(--loader-speed, 1s) * .54); }
.darma-loader-darma-b13-star-rating span:nth-child(5)::after { animation-delay: calc(var(--loader-speed, 1s) * .72); }
@keyframes darma-loader-darma-b13-star-rating-rate { 0% { width: 0; } 22% { width: 100%; } 82% { width: 100%; } 92%, 100% { width: 0; } }

